// Read back a filled EC form (AP 01_1, AP 01_2, AP 02, AP 03_1, FEE) that was printed or
// saved to Word from forms/*.html. Every value sits next to the words the form prints for
// it, and those words come from the forms themselves (src/form-labels.js, generated by
// tools/gen-form-labels.mjs), so this follows the forms when they change.
// A file is taken as an EC form when many of one form's labels are found in it; then its
// values replace what the general rules guessed.
import { FORM_LABELS } from "./form-labels.js";

const norm = (t) => String(t || "").replace(/\s+/g, "").replace(/[:：]+$/, "").toLowerCase();
const PLACEHOLDER = /^[.\s…_\-–]*$/;
const BOX = /^\[\s*\/?\s*\]$/;
const isTicked = (c) => /^\[\s*\/\s*\]/.test(c);
const isUnticked = (c) => /^\[\s*\]/.test(c);
const clean = (v) => String(v || "").replace(/\.{6,}/g, "").replace(/\s+\n/g, "\n").trim();

// "label words value" -> "value", tolerant of spacing differences
function afterLabel(text, label) {
  const chars = [...norm(label)].map((c) => c.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
  const m = String(text).match(new RegExp(`^\\s*${chars.join("\\s*")}\\s*[:：]?\\s*`, "i"));
  return m ? String(text).slice(m[0].length) : null;
}

const split = (v) => clean(v).split(/\n+|\s+(?=\d{1,2}[.)]\s)/).map((x) => x.replace(/^\s*(?:\d{1,2}[.)]|[-•])\s*/, "").trim()).filter(Boolean);
// an amount: a number written with thousands commas wins over a bare year ("2570 828,000")
const money = (v) => {
  // a year named as one ("ประจำปีงบประมาณ พ.ศ. 2569") is never the amount
  const all = String(v).replace(/(?:พ\.\s*ศ\.|ค\.\s*ศ\.|ปี(?:งบประมาณ)?)\s*\d{4}/g, " ").match(/\d{1,3}(?:,\d{3})+(?:\.\d+)?|\d+(?:\.\d+)?/g) || [];
  const m = all.filter((x) => x.includes(",")).pop() || all.pop();
  return m ? Number(m.replace(/,/g, "")) : null;
};
// "(ไทย) ชื่อ (English) Name": the Thai name ends where the English one begins
const afterPrefix = (v) => String(v).split(/\s*\((?:English|อังกฤษ)\)/i)[0];
const count = (v) => { const m = String(v).match(/\d[\d,]*/); return m ? Number(m[0].replace(/,/g, "")) : null; };

// how each form names itself near its top (Thai or English form)
const FORM_TITLE = {
  ap01_1: /แบบรายงานการส่งโครงการวิจัย|Research Protocol Submission Form|AP\s*01_1\//i,
  ap01_2: /เปิดเผยผลประโยชน์ทับซ้อน|Conflict of Interest|AP\s*01_2\//i,
  ap02: /แบบเสนอโครงการวิจัยเพื่อพิจารณา|Research Protocol Proposal|AP\s*02\//i,
  ap03_1: /ข้อมูลและขอความยินยอม|เอกสารข้อมูลสำหรับผู้เข้าร่วม|Participant Information|AP\s*03_1\//i,
  fee: /แจ้งชำระค่าธรรมเนียม|Fee Payment|FEE\//i,
};

// text of the official blank forms (and their dotted "อธิบายรายละเอียด…" prompts)
const FORM_TEXT = new Set(FORM_LABELS.filter((e) => e.kind === "hint").map((e) => norm(e.label.replace(/[…]+$/, ""))));

// Remove the official forms' guidance sentences from a value found by the other rules
// (a researcher may leave "Summarize the significance..." in the filled form).
let guideRes = null;
export function stripFormText(v) {
  if (typeof v !== "string" || !v.trim()) return v;
  guideRes ||= FORM_LABELS.filter((e) => e.kind === "hint" && e.label.length >= 30)
    .map((e) => new RegExp([...e.label.replace(/\s+/g, "")].map((c) => c.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("\\s*"), "g"));
  let out = v;
  for (const re of guideRes) if (out.length >= 25) out = out.replace(re, "");
  // a line that is a piece of a guidance sentence (cut where a rule stopped reading)
  const pieceOfGuide = (l) => { const n = norm(l); return n.length >= 25 && [...FORM_TEXT].some((h) => h.length >= 30 && h.includes(n.slice(0, 40))); };
  return out.split("\n").map((l) => l.trim()).filter((l) => l && !FORM_TEXT.has(norm(l)) && !pieceOfGuide(l)).join("\n").trim();
}

function typed(entry, raw, parseDate) {
  // the next option of a check-box list printed on the same line ends the value
  const v = clean(String(raw || "").split(/\s\[\s*\/?\s*\]\s/)[0]);
  if (!v || PLACEHOLDER.test(v)) return null;
  // the blank form's own prompt left in the cell ("อธิบายรายละเอียด…", "1.") is not an answer
  if (FORM_TEXT.has(norm(v.replace(/[…]+$/, ""))) || /^(?:อธิบาย|ระบุ)[^\n]{0,40}…$/.test(v) || /^(?:\d{1,2}\.\s*)+$/.test(v)) return null;
  switch (entry.fmt) {
    case "list": { const items = split(v); return items.length ? items : null; }
    case "money": return money(v);
    case "date": case "monthyear": return parseDate(v.replace(/^เดือน\s*/, ""));
    default: break;
  }
  if (/(?:sample_size|duration_months|retention_years|_years|_months)$/.test(entry.path)) return count(v);
  // the grant's name is printed with its amount after it on the same row
  if (/grant_name/.test(entry.path)) return v.replace(/\s*\d{1,3}(?:,\d{3})+(?:\.\d+)?\s*(?:บาท)?\s*$/, "").trim() || null;
  return v;
}

function set(o, p, v) {
  const ks = p.split(".");
  let x = o;
  ks.slice(0, -1).forEach((k) => { if (x[k] == null || typeof x[k] !== "object") x[k] = {}; x = x[k]; });
  x[ks[ks.length - 1]] = v;
}

// rows of the table grids as distinct cell texts; a leading check box decides the row
function gridRows(tables) {
  const rows = [];
  for (const t of tables || []) {
    for (const row of t) {
      const cells = [];
      for (const c of row) { const x = String(c.text || "").replace(/[ \t]+/g, " ").trim(); if (x && cells[cells.length - 1] !== x) cells.push(x); }
      if (cells.length) rows.push(cells);
    }
  }
  return rows;
}

// page header and footer the printed forms repeat on every page
export const PAGE_MARK = /^(?:AP\s*0\d(?:_\d)?\/\d{4}|FEE\/\d{4}|หน้า\s*\d+\s*จาก\s*\d+|Version\b.*\bDate\b.*)$/i;
// lines of a PDF: a Thai word broken over two lines is joined without a space
const joinLines = (parts) => parts.reduce((a, l) => (!a ? l : /[ก-๙]$/.test(a) && /^[ก-๙]/.test(l) ? a + l : `${a} ${l}`), "");

// In a PDF a long label breaks over lines ("11.2 ขนาดตัวอย่าง จำนวนผู้เข้าร่วม" / "การวิจัยที่
// ต้องการกี่คน"): join a line to the next while it is only the start of a known label.
function mergeWrappedLabels(lines) {
  const labels = [...new Set(FORM_LABELS.filter((e) => e.kind !== "hint" && e.label.length >= 8).map((e) => norm(e.label)))];
  const out = [];
  for (let i = 0; i < lines.length; i++) {
    let cur = lines[i];
    if (PLACEHOLDER.test(cur)) { out.push(cur); continue; } // a dotted blank is not a label start
    let n = norm(cur.replace(/^\[\s*\/?\s*\]\s*/, ""));
    while (n.length >= 6 && i + 1 < lines.length && !labels.some((lb) => n.startsWith(lb)) && labels.some((lb) => lb.startsWith(n))) {
      cur = joinLines([cur, lines[++i]]);
      n = norm(cur.replace(/^\[\s*\/?\s*\]\s*/, ""));
    }
    out.push(cur);
  }
  return out;
}

export function readEcForm(s, text, tables, parseDate) {
  // the top of the file, page header included ("AP 02/2026"), names the form
  const head = String(text || "").split("\n").slice(0, 20).map((l) => l.trim());
  let lines = String(text || "").split("\n").map((l) => l.trim()).filter((l) => !PAGE_MARK.test(l));
  const rows = gridRows(tables);
  if (!rows.length) lines = mergeWrappedLabels(lines);
  let best = null;
  for (const form of [...new Set(FORM_LABELS.map((e) => e.form))]) {
    const entries = FORM_LABELS.filter((e) => e.form === form);
    const found = {}; // path -> value
    const used = new Map(); // label -> times seen, for labels the form prints twice
    const seen = new Set(); // labels of this form present in the file, filled or not
    const take = (e, v) => { seen.add(e.label); if (v != null && !(e.path in found)) found[e.path] = v; };
    const byLabel = (kind, label) => entries.filter((e) => e.kind === kind && norm(e.label) === label);
    // A cell holding several items, one per line ("ชื่อโครงการวิจัย : ...\nผู้วิจัยหลัก : ...",
    // "2.2 ชื่อผู้รับทุน ...\n2.3 จำนวนเงิน ..."): a value ends where the next item begins.
    const itemStarts = [...new Set(entries.filter((x) => x.kind !== "hint" && x.label.length >= 4).map((x) => norm(x.label)))];
    const cellValue = (v) => {
      const ls = String(v).split("\n");
      const k = ls.findIndex((l, i) => i > 0 && (/^\s*(?:\[\s*\/?\s*\]\s*)?\d{1,2}\.\d{1,2}\s/.test(l) || itemStarts.some((n) => norm(l).startsWith(n))));
      return k < 0 ? v : ls.slice(0, k).join("\n");
    };

    for (const r0 of rows) {
      let r = r0;
      if (r.length > 1 && BOX.test(r[0])) { if (!isTicked(r[0])) continue; r = r.slice(1); }
      // yes/no rows: "label | [/] ใช่ | [ ] ไม่ใช่"
      const yn = byLabel("yn", norm(r[0]))[0];
      if (yn) {
        const t = r.slice(1).find(isTicked);
        if (t) take(yn, !/ไม่ใช่|ไม่มี|^\[\s*\/\s*\]\s*no\b/i.test(t));
        continue;
      }
      // label cells, then the value (labels may take one or two cells: "1 | ค่าตอบแทน...")
      for (let k = Math.min(2, r.length - 1); k >= 1; k--) {
        let label = norm(r.slice(0, k).join(" "));
        let es = byLabel("row", label);
        // "ทุนจากหน่วยงานของรัฐบาล ระบุ <ชื่อทุน> | 50,000": the label cell also holds a value
        if (!es.length && k === 1) {
          es = entries.filter((e) => e.kind === "row" && e.fmt === "money" && e.label.length >= 8 && label.startsWith(norm(e.label)));
          if (es.length) label = norm(es[0].label);
        }
        if (!es.length) continue;
        const n = used.get(label) || 0;
        used.set(label, n + 1);
        const value = r.slice(k).filter((c) => !BOX.test(c)).join(" ");
        // several values in one row ("5 คน" then the calculation after "คน")
        const group = es.length > 1 && !es.some((e) => e.prefix) ? [es[Math.min(n, es.length - 1)]] : es;
        for (const e of group) {
          let v = value;
          if (e.prefix) { const i = v.indexOf(e.prefix); v = i >= 0 ? afterPrefix(v.slice(i + e.prefix.length)) : ""; }
          else if (group.some((g) => g.prefix)) { const p = group.find((g) => g.prefix).prefix; const i = v.indexOf(p); if (i >= 0) v = v.slice(0, i); }
          take(e, typed(e, v, parseDate));
        }
        break;
      }
      // inline: a cell that starts with the words printed before the value
      for (const c of r) {
        if (isUnticked(c)) continue;
        for (const e of entries.filter((x) => x.kind === "inline" && x.label.length >= 4)) {
          const v = afterLabel(c.replace(/^\[\s*\/\s*\]\s*/, ""), e.label);
          if (v != null) take(e, typed(e, cellValue(v), parseDate));
        }
      }
    }
    // inline values in paragraphs ("(ชื่อภาษาไทย) ...", "12.1.2 ...: ..."); and, for a PDF
    // (no table structure), row labels at the start of a line ("7.1 วัตถุประสงค์หลัก เพื่อ...")
    const lineUsed = new Map();
    const rowEntries = entries.filter((x) => x.kind === "row" && x.label.length >= 6);
    const pdf = !rows.length; // no table structure: values may run over several lines
    const labelStarts = [...new Set(entries.filter((x) => x.kind !== "hint" && x.label.length >= 4).map((x) => norm(x.label)))];
    // the form's own guidance ("คำชี้แจง: ให้กรอกข้อมูล ...") also ends a value
    const hintStarts = [...new Set(entries.filter((x) => x.kind === "hint" && norm(x.label).length >= 12).map((x) => norm(x.label).slice(0, 20)))];
    const isStop = (l) => /^\d{1,2}\.(?:\d{1,2}\.?)*\s+\S/.test(l) || labelStarts.some((n) => norm(l).startsWith(n)) || /^\.{6,}$/.test(l) || /^\[\s*\/?\s*\]/.test(l)
      || hintStarts.some((h) => norm(l).startsWith(h));
    // the value that starts on line i and, in a PDF, runs on until the next label
    const runOn = (i, first, e) => {
      const parts = [first];
      if (!pdf) return first;
      let item = /^\s*1[.)]\s/.test(first) ? 2 : 1; // a list may start on the next line
      for (let j = i + 1; j < lines.length; j++) {
        const l = lines[j];
        if (!l) continue;
        if (e.fmt === "list" && new RegExp(`^${item}[.)]\\s`).test(l)) { parts.push(`\n${l}`); item++; continue; }
        if (isStop(l)) break;
        parts.push(l);
      }
      return joinLines(parts).replace(/ ?\n/g, "\n");
    };
    lines.forEach((l0, i) => {
      if (!l0 || l0.includes(" | ")) return;
      if (pdf && isUnticked(l0)) return; // an option not chosen
      const l = pdf ? l0.replace(/^\[\s*\/\s*\]\s*/, "") : l0;
      for (const e of entries.filter((x) => x.kind === "inline" && x.label.length >= 4)) {
        const v = afterLabel(l, e.label);
        if (v != null) take(e, typed(e, runOn(i, v, e), parseDate));
      }
      if (!pdf) return;
      const hit = rowEntries.map((e) => ({ e, v: afterLabel(l, e.label) })).filter((x) => x.v != null)
        .sort((a, b) => b.e.label.length - a.e.label.length)[0];
      if (!hit) return;
      const label = norm(hit.e.label);
      const same = rowEntries.filter((e) => norm(e.label) === label);
      const n = lineUsed.get(label) || 0;
      lineUsed.set(label, n + 1);
      const group = same.some((e) => e.prefix) ? same : [same[Math.min(n, same.length - 1)]];
      const full = runOn(i, hit.v, group[0]);
      for (const e of group) {
        let v = full;
        if (e.prefix) { const k = v.indexOf(e.prefix); v = k >= 0 ? afterPrefix(v.slice(k + e.prefix.length)) : ""; }
        else if (group.some((g) => g.prefix)) { const p = group.find((g) => g.prefix).prefix; const k = v.indexOf(p); if (k >= 0) v = v.slice(0, k); }
        take(e, typed(e, v, parseDate));
      }
    });
    // headings: the paragraphs under "8. ประโยชน์ที่จะได้จากการวิจัย" up to the next heading.
    // The official Word form numbers its headings automatically, so the text has no "8.":
    // a heading is matched with or without its number.
    const noNum = (t) => norm(String(t).replace(/^\s*\d{1,2}(?:\.\d{1,2})*\.?\s*/, ""));
    const allLabels = new Set(entries.flatMap((e) => (e.kind === "hint" ? [] : [norm(e.label), noNum(e.label)])));
    const heads = [...new Set(entries.filter((e) => e.kind === "heading").map((e) => noNum(e.label)).filter((h) => h.length >= 6))];
    const isHead = (l) => { const n = noNum(l); return heads.some((h) => n === h || (n.startsWith(h) && n.length < h.length + 40)); };
    // the form's guidance under a heading, kept in a filled form, is not the answer
    // a line that IS form text (the whole line, or a piece of one long guidance paragraph)
    const hints = new Set(entries.filter((e) => e.kind === "hint").map((e) => norm(e.label)));
    const longHints = [...hints].filter((h) => h.length >= 40);
    const isHint = (l) => { const n = norm(l); return hints.has(n) || (n.length >= 20 && longHints.some((h) => h.startsWith(n))); };
    const numbered = /^\d{1,2}\.(?:\d{1,2}\.?)*\s+\S/; // "8. ...", "12.1 ..." (not "5 คน")
    for (const e of entries.filter((x) => x.kind === "heading")) {
      const h = noNum(e.label);
      const i = lines.findIndex((l) => { const n = noNum(l); return n === h || (n.startsWith(h) && n.length < h.length + 40); });
      if (i < 0 || e.path in found) continue;
      const no = (e.label.match(/^(\d{1,2}(?:\.\d{1,2})*)/) || [])[1];
      const body = [];
      let item = 1; // a list value prints as "1. ...", "2. ...": those lines are its items
      for (let j = i + 1; j < lines.length; j++) {
        const l = lines[j];
        if (!l) continue;
        const sub = (l.match(/^(\d{1,2}(?:\.\d{1,2})*)\.?\s/) || [])[1];
        // "12.1.1 การดำเนินการวิจัยโดยละเอียด" right under "12.1 ..." is a sub-title, not an end
        if (!body.length && no && sub && sub.startsWith(`${no}.`) && l.length < 80) continue;
        // "1. ...", "2. ..." in order under a heading are its content (a list, or numbered
        // points of a paragraph), not the next headings
        if (sub === String(item) && !isHead(l)) { body.push(l); item++; continue; }
        // column titles of the form's own tables (12.2 outcome table) are not a value
        if (/^(?:ตัวแปรที่ต้องการวัด|เครื่องมือที่ใช้วัด|ผู้ประเมินหรือผู้วัดผล|เพิ่มบรรทัดได้)/.test(l) || /^\d{1,2}$/.test(l)) continue;
        // a table row under the heading ends it when it starts with one of the form's labels
        // ("11.1 ประชากรเป้าหมาย | ..."); a table that only holds the answer is the answer
        if (l.includes(" | ")) {
          const cells = [...new Set(l.split(" | ").map((c) => c.trim()).filter(Boolean))];
          if (allLabels.has(norm(cells[0])) || allLabels.has(noNum(cells[0])) || isHead(cells[0])) break;
          const kept = cells.filter((c) => !isHint(c) && !PLACEHOLDER.test(c));
          if (kept.length) body.push(kept.join(" "));
          continue;
        }
        if (numbered.test(l) || allLabels.has(norm(l)) || isHead(l)) break;
        if (isHint(l) || PLACEHOLDER.test(l)) continue;
        // in a PDF a list item or paragraph runs over lines: join it to the line before
        if (pdf && body.length) body[body.length - 1] = joinLines([body[body.length - 1], l]);
        else body.push(l);
      }
      take(e, typed(e, body.join("\n"), parseDate));
    }
    const hits = seen.size;
    // the form names itself at the top ("แบบเสนอโครงการวิจัยเพื่อพิจารณา"); a proposal that
    // shares headings with it ("วัตถุประสงค์ของการวิจัย") does not
    const titled = head.some((l) => FORM_TITLE[form].test(l));
    const seenPaths = new Set(entries.filter((e) => seen.has(e.label)).map((e) => e.path).filter(Boolean));
    if (titled && (!best || hits > best.hits)) best = { form, found, hits, seenPaths };
  }
  // an EC form needs its title and many of its labels
  if (!best || best.hits < 8) return null;
  for (const [p, v] of Object.entries(best.found)) set(s, p, v);
  // a place the form has and the file shows blank stays blank (what the other rules would
  // put there is the form's own guidance); a place not found in the file keeps their value
  best.paths = [...best.seenPaths];
  for (const p of best.paths) {
    if (p in best.found) continue;
    const cur = p.split(".").reduce((x, k) => (x == null ? undefined : x[k]), s);
    if (typeof cur === "string") set(s, p, "");
    else if (Array.isArray(cur)) set(s, p, []);
  }
  if (rows.length) readPeopleTables(s, rows);
  else readPeopleLines(s, lines);
  return best;
}

// The same tables in a PDF: "1 อ.ดร. ก ข สำนักวิชาเทคโนโลยีดิจิทัล" with the rest of the cell on
// the next lines; the name ends where the school begins.
const SCHOOL = /(สำนักวิชา|คณะ|ภาควิชา|สาขาวิชา|สาขา|ศูนย์|สถาบัน|มหาวิทยาลัย|School|Faculty|Department)/;
function readPeopleLines(s, lines) {
  const groups = [];
  let cur = null;
  let last = null;
  for (const l of lines) {
    if (/ผู้วิจัยร่วม\s*\(Co-?Investigators?\)|ที่ปรึกษาโครงการวิจัย\s*\(Research Advisor\)/i.test(l)) { cur = []; groups.push(cur); last = null; continue; }
    if (!cur) continue;
    if (/ผู้ประสานงาน|^\d{1,2}\.\s/.test(l)) { cur = null; continue; }
    const m = l.match(/^(\d{1,2})\s+(.+)$/);
    if (m) { last = { text: m[2] }; cur.push(last); continue; }
    if (/^\d{1,2}$/.test(l) || /^\.{6,}/.test(l) || /ลำดับ|ตำแหน่งวิชาการ|^สกุล$|เบอร์โทร/.test(l)) { last = null; continue; }
    if (last) last.text = joinLines([last.text, l]);
  }
  const person = ({ text }) => {
    const email = (text.match(/[\w.+-]+@[\w-]+\.[\w.-]+/) || [""])[0];
    const phone = (text.match(/0\d[\d\-\s]{6,12}\d/) || [""])[0].trim();
    const rest = text.replace(email, "").replace(phone, "").trim();
    const k = rest.search(SCHOOL);
    return { title_th: (k > 0 ? rest.slice(0, k) : rest).trim(), name_en: "", status: "lecturer", affiliation: k > 0 ? rest.slice(k).trim() : "", phone, email };
  };
  if (groups[0]?.length) s.co_investigators = groups[0].map(person);
  if (groups[1]?.length) s.advisors = groups[1].map(person);
}

// Co-investigators and advisors: numbered rows "1 | name | school | phone / email" in the
// tables that follow "ผู้วิจัยร่วม" and "ที่ปรึกษา" (in that order on AP 02).
function readPeopleTables(s, rows) {
  const groups = [];
  let cur = null;
  for (const r of rows) {
    const head = r.join(" ");
    if (/ตำแหน่งวิชาการ.*ชื่อ.*สกุล/.test(head) && /สาขาวิชา|หน่วยงาน/.test(head) && r.length >= 3 && !/^\d+$/.test(r[0])) {
      cur = [];
      groups.push(cur);
      continue;
    }
    if (cur && /^\d{1,2}$/.test(r[0])) {
      if (r.length >= 2 && !PLACEHOLDER.test(r[1])) cur.push(r);
      continue;
    }
    if (cur && !/^\d{1,2}$/.test(r[0])) cur = null;
  }
  const person = (r) => {
    const contact = r.slice(3).join(" ");
    const email = (contact.match(/[\w.+-]+@[\w-]+\.[\w.-]+/) || [""])[0];
    const phone = (contact.match(/0\d[\d\-\s]{6,12}\d/) || [""])[0].trim();
    return { title_th: r[1], name_en: "", status: "lecturer", affiliation: PLACEHOLDER.test(r[2] || "") ? "" : r[2] || "", phone, email };
  };
  if (groups[0]?.length) s.co_investigators = groups[0].map(person);
  if (groups[1]?.length) s.advisors = groups[1].map(person);
}
